def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    prev_need = []
    david_like_bid = None
    bob_like_bid = None

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('alive'):
                prev_need.append(float(bid))
            req = opp.get('water_requirement', 0)
            sal = opp.get('daily_salary', 0)
            if req == 13 and sal == 70:
                if bid <= 120:
                    david_like_bid = float(bid)
                else:
                    bob_like_bid = float(bid)

    alive_count = len(alive)
    if alive_count == 0:
        return float(min(budget, 18.0))

    scarcity = 0.0
    if supply <= 16:
        scarcity = 1.0
    elif supply <= 18:
        scarcity = 0.7
    elif supply <= 20:
        scarcity = 0.4
    else:
        scarcity = 0.1

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 6:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days == 1:
        urgency += 0.35

    pressure = 0.0
    if prev_need:
        highest_prev = max(prev_need)
        second_prev = sorted(prev_need)[-2] if len(prev_need) >= 2 else highest_prev
        pressure = max(highest_prev, second_prev * 0.95)
    else:
        highest_prev = 0.0
        second_prev = 0.0

    target = 0.0

    if hp <= 2 or no_water_days >= 2:
        if david_like_bid is not None:
            target = max(96.0, min(113.0, david_like_bid + 2.0))
        else:
            target = max(92.0, min(112.0, pressure + 2.0))
    elif scarcity >= 0.7:
        if david_like_bid is not None:
            target = min(112.0, david_like_bid + 1.5)
        elif pressure > 0:
            target = min(112.0, pressure + 1.5)
        else:
            target = 78.0
    else:
        if bob_like_bid is not None and bob_like_bid >= 130:
            target = 38.0 + 8.0 * scarcity + 10.0 * urgency
        elif david_like_bid is not None:
            target = max(48.0, min(92.0, david_like_bid - 8.0 + 8.0 * scarcity + 10.0 * urgency))
        elif pressure > 0:
            target = max(44.0, min(88.0, pressure * 0.72 + 8.0 * scarcity + 10.0 * urgency))
        else:
            target = 46.0 + 10.0 * scarcity + 8.0 * urgency

    if day >= 8:
        target += 8.0
    if day >= 9:
        target += 10.0

    reserve_floor = 0.0
    days_left = max(0, 10 - int(day))
    if days_left >= 2 and hp > 3:
        reserve_floor = min(budget * 0.45, 55.0)

    bid = min(float(budget), float(target))
    if budget - bid < reserve_floor and hp > 3 and no_water_days == 0:
        bid = max(0.0, budget - reserve_floor)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(float(budget), 98.0))

    if bid < 0:
        bid = 0.0
    return float(round(min(float(budget), bid), 2))

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 9
    MY_DAILY_SALARY = 90
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], MY_DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = MY_DAILY_SALARY

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid > MY_DAILY_SALARY * 0.75:
            base_bid = max(base_bid, highest_prev_bid * 1.05)
        else:
            base_bid = max(base_bid, highest_prev_bid + MY_DAILY_SALARY * 0.15)

    if my_status['hp'] <= MY_WATER_REQ:
        base_bid = max(base_bid, MY_DAILY_SALARY * 1.2)
        if my_status['hp'] <= MY_WATER_REQ * 0.5:
            base_bid = max(base_bid, MY_DAILY_SALARY * 1.5)

    current_day = day_context['day']
    if current_day > EPISODE_DAYS * 0.7:
        base_bid *= 1.1

    supply_level = day_context['supply']
    if supply_level <= 15:
        base_bid *= 1.15
    elif supply_level <= 20:
        base_bid *= 1.05

    final_bid = min(my_status['budget'], base_bid)

    if my_status['budget'] > 0 and final_bid < MY_DAILY_SALARY * 0.1:
         final_bid = min(my_status['budget'], MY_DAILY_SALARY * 0.1)
    elif my_status['budget'] == 0:
        final_bid = 0.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    hp = my_status['hp']
    budget = my_status['budget']
    supply = day_context['supply']
    day = day_context['day']
    no_water = my_status['no_water_days']

    alive_opps = {k: v for k, v in opponents_status.items() if v['alive']}
    prev_bids = []
    for opp in alive_opps.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Determine urgency
    need_water = (hp <= 3) or (no_water >= 2)

    if need_water:
        if prev_bids:
            target = max(prev_bids) + 1.5
        else:
            target = DAILY_SALARY * 0.85
        # reduce if supply is high (more winners possible)
        if supply >= 20:
            target *= 0.85
        bid = min(budget, target)
        return max(0.1, bid)
    elif hp <= 6:
        # moderate: try to win at reasonable price
        if prev_bids:
            avg_prev = sum(prev_bids) / len(prev_bids)
            target = avg_prev * 0.9
        else:
            target = DAILY_SALARY * 0.5
        if supply >= 20:
            target *= 0.8
        bid = min(budget, target)
        return max(0.1, bid)
    else:
        # healthy: save money
        bid = min(budget, DAILY_SALARY * 0.3)
        return max(0.1, bid)
